#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string text, word, id;
    cin >> text;
    vector<pair<string, string>> entries;
    size_t m, total = 0;
    if (cin >> m)
        while (cin >> word >> id) { total += word.size(); entries.push_back({word, id}); }
    // Trie over ASCII; child 0 means "none" (the root is never a child).
    vector<int> child((total + 1) * 128, 0), terminal(total + 1, -1);
    int nodes = 1;
    for (int e = 0; e < (int)entries.size(); e++) {
        int node = 0;
        for (unsigned char ch : entries[e].first) {
            int &next = child[node * 128 + ch];
            if (!next) next = nodes++;
            node = next;
        }
        if (terminal[node] < 0) terminal[node] = e; // keep the first identifier only
    }
    // Greedy longest match from the current position.
    vector<string> answer;
    size_t i = 0;
    while (i < text.size()) {
        int node = 0, found = -1;
        size_t j = i, end = i;
        while (j < text.size() && (unsigned char)text[j] < 128 && child[node * 128 + (unsigned char)text[j]]) {
            node = child[node * 128 + (unsigned char)text[j]];
            j++;
            if (terminal[node] >= 0) found = terminal[node], end = j;
        }
        if (found < 0) answer.push_back(string(1, text[i++]));
        else answer.push_back(entries[found].second), i = end;
    }
    string out = to_string(answer.size());
    for (auto &s : answer) out += ' ' + s;
    cout << out << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tokens.add(st.nextToken());
        }
        String text = tokens.get(0);
        int total = 0;
        for (int j = 2; j + 1 < tokens.size(); j += 2) total += tokens.get(j).length();
        // Trie over ASCII; child 0 means "none" (the root is never a child).
        int[] child = new int[(total + 1) * 128];
        int[] terminal = new int[total + 1];
        Arrays.fill(terminal, -1);
        int nodes = 1;
        for (int j = 2; j + 1 < tokens.size(); j += 2) {
            String word = tokens.get(j);
            int node = 0;
            for (int c = 0; c < word.length(); c++) {
                int at = node * 128 + word.charAt(c);
                if (child[at] == 0) child[at] = nodes++;
                node = child[at];
            }
            if (terminal[node] < 0) terminal[node] = j + 1; // keep the first identifier only
        }
        // Greedy longest match from the current position.
        StringBuilder sb = new StringBuilder();
        int count = 0, i = 0;
        while (i < text.length()) {
            int node = 0, found = -1, j = i, end = i;
            while (j < text.length() && text.charAt(j) < 128 && child[node * 128 + text.charAt(j)] != 0) {
                node = child[node * 128 + text.charAt(j)];
                j++;
                if (terminal[node] >= 0) { found = terminal[node]; end = j; }
            }
            sb.append(' ');
            if (found < 0) sb.append(text.charAt(i++));
            else { sb.append(tokens.get(found)); i = end; }
            count++;
        }
        System.out.println(count + sb.toString());
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	var tokens []string
	for sc.Scan() {
		tokens = append(tokens, sc.Text())
	}
	text := tokens[0]
	total := 0
	for j := 2; j+1 < len(tokens); j += 2 {
		total += len(tokens[j])
	}
	// Trie over ASCII; child 0 means "none" (the root is never a child).
	child := make([]int32, (total+1)*128)
	terminal := make([]int, total+1)
	for i := range terminal {
		terminal[i] = -1
	}
	nodes := int32(1)
	for j := 2; j+1 < len(tokens); j += 2 {
		node := int32(0)
		for _, ch := range []byte(tokens[j]) {
			at := int(node)*128 + int(ch)
			if child[at] == 0 {
				child[at] = nodes
				nodes++
			}
			node = child[at]
		}
		if terminal[node] < 0 {
			terminal[node] = j + 1 // keep the first identifier only
		}
	}
	// Greedy longest match from the current position.
	var answer []string
	for i := 0; i < len(text); {
		node, found, j, end := int32(0), -1, i, i
		for j < len(text) && text[j] < 128 && child[int(node)*128+int(text[j])] != 0 {
			node = child[int(node)*128+int(text[j])]
			j++
			if terminal[node] >= 0 {
				found, end = terminal[node], j
			}
		}
		if found < 0 {
			answer = append(answer, text[i:i+1])
			i++
		} else {
			answer = append(answer, tokens[found])
			i = end
		}
	}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	out.WriteString(strconv.Itoa(len(answer)))
	for _, s := range answer {
		out.WriteString(" " + s)
	}
	out.WriteString("\n")
}
